ge 12) - FY 1991-1995\ndata_1996 = {\n    1991: (760375, 293885),\n    1992: (789266, 302426),\n    1993: (841241, 311934),\n    1994: (922161, 335026),\n    1995: (999496, 351080),\n}\n\n# From 2001 bulletin (page 16) - FY 1996-2000\ndata_2001 = {\n    1996: (1085271, 367492),\n    1997: (1186987, 391989),\n    1998: (1305621, 415800),\n    1999: (1382834, 444468),\n    2000: (1544455, 480583),\n}\n\n# From 2006 bulletin (page 19) - FY 2001-2005\ndata_2006 = {\n    2001: (1483525, 507519),\n    2002: (1337730, 515321),\n    2003: (1258265, 523842),\n    2004: (1345040, 534744),\n    2005: (1575874, 577475),\n}\n\n# From 2011 bulletin (page 20) - FY 2006-2010 (use final actuals from this bulletin)\ndata_2011 = {\n    2006: (1797946, 608382),\n    2007: (1932359, 635088),\n    2008: (1865279, 658045),\n    2009: (1450355, 654010),\n    2010: (1530058, 631688),\n}\n\n# Combine all data - using the most recent bulletin for each year\nall_data = {}\nall_data.update(data_1996)\nall_data.update(data_2001)\nall_data.update(data_2006)\nall_data.update(data_2011)\n\n# Sort by year\nyears = sorted(all_data.keys())\nprint(\"Data for FY 1991-2010:\")\nprint(\"Year | On-Budget | Off-Budget\")\nprint(\"-\" * 35)\nfor year in years:\n    on_budget, off_budget = all_data[year]\n    print(f\"{year} | {on_budget:,} | {off_budget:,}\")\n\n# Calculate R-squared\n# We'll use off-budget as X (independent variable) and on-budget as Y (dependent variable)\n# Or typically: on-budget vs off-budget\n\nimport numpy as np\n\nx = np.array([all_data[y][1] for y in years])  # off-budget\ny = np.array([all_data[y][0] for y in years])  # on-budget\n\n# Calculate linear regression\nslope, intercept = np.polyfit(x, y, 1)\ny_pred = slope * x + intercept\n\n# Calculate R-squared\nss_res = np.sum((y - y_pred) ** 2)\nss_tot = np.sum((y - np.mean(y)) ** 2)\nr_squared = 1 - (ss_res / ss_tot)\n\nprint(f\"\\nLinear Regression Results:\")\nprint(f\"Slope: {slope}\")\nprint(f\"Intercept: {intercept}\")\nprint(f\"R-squared: {r_squared}\")\nprint(f\"\\nR-squared (rounded to 4 decimal places): {round(r_squared, 4)}\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
